INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5852837, 851705, 43594, '<td valign="top">nice idea, distracting elements in the image (nails)</td>', 'nice idea, distracting elements in the image (nails)', '2010-02-04 13:23:54.000000', NULL, 1),
(5852842, 851459, 43594, '<td valign="top">brilliant idea, well implemented!</td>', 'brilliant idea, well implemented!', '2010-02-04 13:28:21.000000', NULL, 1),
(5852949, 851330, 29904, '<td valign="top">looks like you forgot to rotate this, bird appears upside down.</td>', 'looks like you forgot to rotate this, bird appears upside down.', '2010-02-04 15:15:10.000000', NULL, 1),
(5852971, 850726, 29904, '<td valign="top">oof.  unfortunately the sharp frame line only emphasizes this.</td>', 'oof.  unfortunately the sharp frame line only emphasizes this.', '2010-02-04 15:36:41.000000', NULL, 1),
(5852983, 850948, 86447, '<td valign="top">Yeah.  A 10.   :)</td>', 'Yeah.  A 10.   :)', '2010-02-04 15:47:30.000000', NULL, 1),
(5852984, 851574, 86447, '<td valign="top">Fabulous 10.</td>', 'Fabulous 10.', '2010-02-04 15:47:42.000000', NULL, 1),
(5852986, 851361, 86447, '<td valign="top">SUCH a clever title to accompany this wonderful image!   Good stuff!</td>', 'SUCH a clever title to accompany this wonderful image!   Good stuff!', '2010-02-04 15:48:06.000000', NULL, 1),
(5852987, 851707, 86447, '<td valign="top">LOL!   So clever!  And well shot!</td>', 'LOL!   So clever!  And well shot!', '2010-02-04 15:49:23.000000', NULL, 1),
(5853085, 851518, 17507, '<td valign="top">Ah, you''ve boldly entered what appears to be the only landscape in the challenge. Works for me, though--red peppers and flaming shot glasses are not the only things that convey ''hotness.'' Here we have the blazing sun in the desert in a stark B/W study--if that doesn''t convey hotness, I don''t know what does.<br/> <br/>This is my top pick for this challenge--I hope you make at least the top 10!</td>', 'Ah, you''ve boldly entered what appears to be the only landscape in the challenge. Works for me, though--red peppers and flaming shot glasses are not the only things that convey ''hotness.'' Here we have the blazing sun in the desert in a stark B/W study--if that doesn''t convey hotness, I don''t know what does. This is my top pick for this challenge--I hope you make at least the top 10!', '2010-02-04 17:32:15.000000', NULL, 1),
(5853087, 850939, 17507, '<td valign="top">Awesome work... great colors, composition, DOF, and conceptually very strong. As a bit of a LotR nerd, I''m bothered by the fact that the ring isn''t a plain gold band--but this is nonetheless a very pretty image to look at. <br/> <br/>One of my top picks--good luck in the final ranking!</td>', 'Awesome work... great colors, composition, DOF, and conceptually very strong. As a bit of a LotR nerd, I''m bothered by the fact that the ring isn''t a plain gold band--but this is nonetheless a very pretty image to look at.  One of my top picks--good luck in the final ranking!', '2010-02-04 17:33:17.000000', NULL, 1),
(5853092, 850861, 17507, '<td valign="top">Hahah, I love the humor in this shot, and our hapless hero has an appropriately nonplussed exception. Lighting winds up a bit flat, which keeps me from giving this more than an 8, but it''s still one of my favorites from this challenge. Good luck!</td>', 'Hahah, I love the humor in this shot, and our hapless hero has an appropriately nonplussed exception. Lighting winds up a bit flat, which keeps me from giving this more than an 8, but it''s still one of my favorites from this challenge. Good luck!', '2010-02-04 17:34:40.000000', NULL, 1),
(5853101, 851459, 17507, '<td valign="top">Image is very strong--well lit, nicely composed, sharp, edgy, and of course sexy. I don''t really get the title, though--where does the ''Hell'' part come from? Nonetheless a great shot, and I hope to see it in at least the top 10.</td>', 'Image is very strong--well lit, nicely composed, sharp, edgy, and of course sexy. I don''t really get the title, though--where does the ''Hell'' part come from? Nonetheless a great shot, and I hope to see it in at least the top 10.', '2010-02-04 17:37:27.000000', NULL, 1),
