(5863740, 851459, 74911, '<td valign="top">I am really sorry about this DQ. It still remains a wonderful piece of art though.</td>', 'I am really sorry about this DQ. It still remains a wonderful piece of art though.', '2010-02-11 19:04:49.000000', NULL, 0),
(5863754, 851402, 90495, '<td valign="top">Something similar happened to me once. It took over 3 months for my eyelashes to grow back to what they were.<br/> <br/>Great image and very well executed. Congrats.</td>', 'Something similar happened to me once. It took over 3 months for my eyelashes to grow back to what they were. Great image and very well executed. Congrats.', '2010-02-11 19:31:03.000000', NULL, 0),
(5863755, 850939, 90495, '<td valign="top">Love the blues in this. Great image. Congrats.</td>', 'Love the blues in this. Great image. Congrats.', '2010-02-11 19:32:46.000000', NULL, 0),
(5863758, 850948, 90495, '<td valign="top">Once again you amaze me with another great image. I''m curious, are the flames real or did you use another image? No matter, you did an exceptional job. Congrats.</td>', 'Once again you amaze me with another great image. I''m curious, are the flames real or did you use another image? No matter, you did an exceptional job. Congrats.', '2010-02-11 19:34:54.000000', NULL, 0),
(5863762, 851459, 90495, '<td valign="top">Sorry about the DQ.  It always breaks my heart to see a winner get DQed for reasons such as this. My worst reason is ''not submitting the original when asked to validate'' that just burns me up.<br/> <br/>No matter though, it''s a great image. Now get your camera checked so this doesn''t happen again. ;)</td>', 'Sorry about the DQ.  It always breaks my heart to see a winner get DQed for reasons such as this. My worst reason is ''not submitting the original when asked to validate'' that just burns me up. No matter though, it''s a great image. Now get your camera checked so this doesn''t happen again. ;)', '2010-02-11 19:42:32.000000', NULL, 0),
(5863767, 851459, 50578, '<td valign="top">Honestly I don''t know for sure what I would be more bummed about,  the DQ which obviously does suck. or the fact that 28 people scored this 4 or lower when it was a Blue Ribbon Winning Effort.   10  1''s is absolutey pathetic.  This is not a case of it being a bad photo. It is a case of people who shouldn''t vote on an image at all if the content is not to their liking and they are only slapping it a 1 for that reason.  Congrats on the Ribbon anyway, and sorry that you had it taken away.</td>', 'Honestly I don''t know for sure what I would be more bummed about,  the DQ which obviously does suck. or the fact that 28 people scored this 4 or lower when it was a Blue Ribbon Winning Effort.   10  1''s is absolutey pathetic.  This is not a case of it being a bad photo. It is a case of people who shouldn''t vote on an image at all if the content is not to their liking and they are only slapping it a 1 for that reason.  Congrats on the Ribbon anyway, and sorry that you had it taken away.', '2010-02-11 19:48:02.000000', NULL, 0),
(5863778, 851402, 59029, '<td valign="top">Great work, esp all on your own!  Congrats!</td>', 'Great work, esp all on your own!  Congrats!', '2010-02-11 19:58:20.000000', NULL, 0),
(5863800, 851402, 30214, '<td valign="top">looks yummy! congrats on your (unexpected) ribbon Mark! :)</td>', 'looks yummy! congrats on your (unexpected) ribbon Mark! :)', '2010-02-11 20:19:11.000000', NULL, 0),
(5863802, 851459, 67343, '<td valign="top">Sorry to here about your DQ, such a great photo is still a winner.</td>', 'Sorry to here about your DQ, such a great photo is still a winner.', '2010-02-11 20:20:31.000000', NULL, 0),
(5863804, 851459, 70661, '<td valign="top">So sorry about the dq but I still love the pic!</td>', 'So sorry about the dq but I still love the pic!', '2010-02-11 20:22:16.000000', NULL, 0),
(5863831, 851459, 69325, '<td valign="top">dont be too hard on yourself, the important thing is the producing of a great image! not the ribbon (easy for me to say huh?)</td>', 'dont be too hard on yourself, the important thing is the producing of a great image! not the ribbon (easy for me to say huh?)', '2010-02-11 20:43:53.000000', NULL, 0),
(5863840, 851402, 67343, '<td valign="top">Congrats on your ribbon Mark, great work.</td>', 'Congrats on your ribbon Mark, great work.', '2010-02-11 20:47:54.000000', NULL, 0),
(5863871, 851459, 77196, '<td valign="top">Whatever the date, whenever the time, challenge or no, this is a great shot! Congratulations on a job well done. <br/>Me thinks it should be obvious that the picture had to be taken within the challenge date range - the image date is not before the challenge, and the image had to exist in order to be included in the voting. What a bummer! <br/></td>', 'Whatever the date, whenever the time, challenge or no, this is a great shot! Congratulations on a job well done. Me thinks it should be obvious that the picture had to be taken within the challenge date range - the image date is not before the challenge, and the image had to exist in order to be included in the voting. What a bummer! ', '2010-02-11 21:05:49.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5863911, 851459, 69668, '<td valign="top">Awww Jorge.......sorry about the DQ.  Same thing has happened to me.  My date was set 12 hours wrong and I was outside the correct submission window.  Nonetheless....it is an incredible image and I am so happy to see you beautiful work again.  I hope that you stay around for awhile.  Jennifer</td>', 'Awww Jorge.......sorry about the DQ.  Same thing has happened to me.  My date was set 12 hours wrong and I was outside the correct submission window.  Nonetheless....it is an incredible image and I am so happy to see you beautiful work again.  I hope that you stay around for awhile.  Jennifer', '2010-02-11 21:23:56.000000', NULL, 0),
(5863920, 851402, 69668, '<td valign="top">Terrific....congrats on such a great image.</td>', 'Terrific....congrats on such a great image.', '2010-02-11 21:26:28.000000', NULL, 0),
(5863928, 850948, 98022, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by dswann:</b></div><hr/><i> Good composition and lighting. Congrats on the red! </i></td></tr></table> <br/> <br/>And now, congrats on the blue!</td>', 'Originally posted by dswann: Good composition and lighting. Congrats on the red!   And now, congrats on the blue!', '2010-02-11 21:36:49.000000', NULL, 0),
